create function pg_temp.reopen(p_id uuid,p_end uuid,p_day date default current_setting('test.today')::date+14,p_reason text default 'Synthetic correction') returns uuid language sql as $$
 select public.reopen_item_period(current_setting('test.tenant')::uuid,p_id,current_setting('test.item')::uuid,p_end,p_day,p_reason);
$$;
create function pg_temp.correct_end(p_id uuid,p_end uuid,p_action text default 'return',p_reason text default 'Synthetic correction') returns uuid language sql as $$
 select public.correct_item_period_end(current_setting('test.tenant')::uuid,p_id,current_setting('test.item')::uuid,p_end,p_action,p_reason);
$$;
